INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65942825', 65942825, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL BINA ADMINISTRASI KEWILAYAHAN', 'Tenaga Ahli Pengembangan Sistem Informasi Pelaporan Gubernur Sebagai Wakil Pemerintah Pusat (SIPGWPP)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Keberadaan Gubernur sebagai Wakil Pemerintah Pusat telah diatur dalam Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah dan Peraturan Pemerintah Nomor 33 Tahun 2018 tentang Pelaksanaan Tugas dan Wewenang Gubernur sebagai Wakil Pemerintah Pusat, dimana dalam melaksanakan pembinaan dan pengawasan terhadap penyelenggaraan Urusan Pemerintahan yang menjadi kewenangan Daerah Kabupaten/Kota dan Tugas Pembantuan oleh Daerah Kabupaten/Kota, Presiden dibantu oleh Gubernur sebagai Wakil Pemerintah Pusat. Presiden melimpahkan 46 (empat puluh enam) tugas dan wewenang kepada Gubernur sebagai Wakil Pemerintah Pusat secara atributif sebagaimana diamanatkan dalam Undang-Undang nomor 23 Tahun 2014 tentang Pemerintahan Daerah. Disamping tugas dan wewenang yangbersifat atributif, Presiden melalui Menteri/ Kepala Lembaga dapat melimpahkan tugas dan wewenang yang bersifat delegatif sesuai dengan Peraturan Perundang-Undangan. Dan untuk memastikan agar Gubernur sebagai Wakil Pemerintah Pusat benar-benar menjalankan tugas dan fungsinya sebagaimana yang telah diamanatkan melalui Undang-Undang, Direktorat Jendral Bina Administrasi Kewilayahan Kementrian Dalam Negeri pada tahun 2021 telah mendesign alat ukur berupa matriks Indikator Keberhasilan (Key Performance Indikator) dan menginisiasi pengembangan Sistem Informasi Pelaporan Gubernur Sebagai Wakil Pemerintah Pusat (SIP GWPP) sebagai media pelaporan terintegrasi berbasis teknologi informasi yang digunakan oleh Gubernur dan jajarannya untuk menginnformasikan & melaporkan aktifitasnya sebagai wakil pemerintah pusat sebagaimana yang telah diamanatkan oleh Undang-Undang. Penilaian Kinerja ini diterapkan secara bertahap sejak tahun 2022. Seiring dengan pelaksanaan indikator tersebut, SIP GWPP sebagai media pelaporan juga terus dipelihara, disempurnakan & dimutakhirkan mengikuti evaluasi, masukan, dan kebutuhan yang terus berkembang. Ditahun 2026, Direktorat Jendral Bina Administrasi Kewilayahan Kementrian Dalam Negeri menargetkan terselenggaranya 7 (Tujuh) dari 46 tugas dan wewenang Gubernur sebagai Wakil Pemerintah Pusat sesuai amanat PP Nomor 33 Tahun 2018 dan tata kelola pelaksanaan tugas sebagaimana diamanatkan dalam Peraturan Menteri Dalam Negeri Nomor 12 Tahun 2021 tentang Peraturan Pelaksanaan PP Nomor 33 Tahun 2018. Selain itu, sebagai bentuk langkah kongkrit dukungan Kementrian Dalam Negeri dalam mensukseskan kegiatan pemerintah sehubungan dengan Program Prioritas Presiden, Kementrian Dalam Negeri khususnya Direktorat Jendral Bina Administrasi Kewilayahan berinisiatif untuk Teknologi informasi merupakan salah satu hal penting dalam kelancaran kegiatan istansi pemerintah, termasuk dalam hal pengolahan, penyimpanan dan pengaksesan informasi. Sesuai dengan pasal 3 ayat 2 dalam Peraturan Menteri Dalam Negeri Tahun 2017 tentang Pedoman Presiden Nomor 39 tahun 2019 tentang Satu Data Indonesia bahwa untuk memperoleh data akurat, mutakhir, terpadu dan dapat dipertanggungjawabkan, mudah diakses dan dibagi pakaikan, maka diperlukan perbaikan tata kelola data yang dihasilkan melalui penyelenggaraan Satu Data Indonesia di lingkup Kementerian Dalam Negeri, khususnya Direktorat Jenderal Bina Administasi Kewilayahan (Ditjen Adwil).', 'Pelaksana kegiatan Pemutakhiran Sistem Informasi Pelaporan Gubernur sebagai Wakil Pemerintah Pusat & Pengembangan Sistem Informasi Pelaporan Program Prioritas Presiden melalui Pemanfaatan Sistem Informasi yang Terintegrasi harus memenuhi beberapa persyaratan yang dipenuhi. Adapun persyaratan- persyaratan yang diperlukan adalah mampu menyediakan tenaga teknis melalui surat pernyataan dengan kualifikasi sebagai berikut: a. Tenaga Ahli Analisa Data dan Sistem Informasi, 1 (satu) orang, Pendididikan S1 Teknik Informatika/ Teknik Komputer/ Sistem Informasi/ Teknik Elektro/ Management/ Management Informatika. Pengalaman minimal 10 Tahun. b. Tenaga Ahli System Informasi Aplikasi 1 (satu) orang, Pendididikan S1 Teknik Informatika/Teknik Komputer/Sistem Informasi/Teknik Elektro dan Jurusan Teknik Lainnya dibidang IT, Pengalaman minimal 8 Tahun.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2440428);
