INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65898642', 65898642, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '693530 BALAI PENGELOLAAN HUTAN LESTARI WILAYAH XVI', 'Pengadaan Jasa Tenaga Kerja Outsourcing pada Kantor Balai Pengelolaan Hutan Lestari Wilayah XVI Ambon Tahun 2026', 'Jasa Lainnya', 'E-Purchasing', 'Maluku, Ambon (Kota)', 197500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Dalam rangka melaksanakan pekerjaan pengamanan, kebersihan, sopir, dan pramubakti : 4 orang, sarana dan prasarana yang biasa disebut dalam kategori objek vital pada Gedung Kantor BPHL WILAYAH XVI AMBON Tahun Anggaran 2026, yang dilakukan pada setiap hari secara rutin diperlukan bantuan tenaga jasa. Mengingat pentingnya kondisi keamanan, kebersihan kantor maka penanganan tidak bisa dilakukan sendiri, dan akan diserahkan penanganannya kepada pihak ketiga yaitu perusahaan penyedia jasa pengamanan yang dilakukan oleh satuan pengamanan (SATPAM), jasa Sopir (Driver), jasa Tenaga Kebersihan (Cleaning Service) dan jasa Pramubakti. Sasaran yang ingin dicapai adalah dengan tersedianya tenaga satuan pengamanan dan Tenaga Kebersihan yang profesional, handal dan sigap dapat tercapai tingkat pengamanan dan Kebersihan Kantor yang maksimal sesuai kebutuhan pada Gedung Kantor BPHL WILAYAH XVI AMBON terletak di Jl. Kebun Cengkeh Kota Ambon. Kegiatan ini dibiayai dari sumber pendanaan: Daftar Isian Pelaksanaan Anggaran (DIPA) Bagian Anggaran (BA) 029 Satuan Kerja BPHL WILAYAH XIV AMBON Tahun 2025 dengan jumlah anggaran diperkirakan sebesar Rp.197.000.000,- (Seratus Sembilan Puluh Juta Rupiah).', 'Paket pengadaan ini terbuka untuk penyedia barang/jasa yang teregistrasi pada Layanan Pengadaan Secara Elektronik (LPSE) dan memenuhi persyaratan sebagai berikut : a. Peserta harus memiliki Surat Ijin Usaha dari instansi yang berwenang dan masih berlaku, pada bidang jasa pengamanan. b. Memiliki Ijin operasional penyedia jasa pengamanan (BUPJTP) dari POLRI yang masih berlaku; c. Memiliki ijin jasa penyelenggara Outsourching; d. Memiliki sertifikat kepesertaan Jaminan Sosial Tenaga Kerja / BPJS Ketenagakerjaan yang masih berlaku yang dikeluarkan oleh instansi pemerintah yang berwenang; e. Memiliki setifikat Manajemen Mutu ISO 9001:2008; f. Memiliki sertifikat Manajemen Kesehatan dan Keselamatan Kerja (K3) atau OHSAS; g. Perusahaan yang bersangkutan dan manajemennya tidak dalam pengawasan pengadilan, tidak pailit, kegiatan usahanya tidak sedang dihentikan dan/atau direksi yang bertindak untuk dan atas nama perusahaan atau peserta perorangan tidak sedang dalam menjalani sanksi pidana; h. salah satu dan/atau semua pengurus dan badan usahanya atau peserta perorangan tidak masuk dalam Daftar Hitam; i. memiliki NPWP dan telah memenuhi kewajiban perpajakan tahun pajak terakhir (SPT Tahunan 2017); j. peserta berbentuk badan usaha harus memperoleh minimal1 (satu) pekerjaan sebagai penyedia dalam kurun waktu 4 (empat) tahun terakhir, baik di lingkungan pemerintah maupun swasta termasuk pengalaman subkontrak, kecuali bagi penyedia yang baru berdiri kurang dari 3 (tiga) tahun; k. Dalam hal peserta berbentuk badan usaha akan melakukan kemitraan, maka peserta wajib mempunyai perjanjian Kerja Sama Operasi/kemitraan yang memuat persentase kemitraan dan perusahaan yang mewakili kemitraan tersebut;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2440997);
