INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65900634', 65900634, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'BALAI PELATIHAN DAN PENGEMBANGAN TEKNOLOGI INFORMASI DAN KOMUNIKASI', 'Pengadaan Kebutuhan Operasional dan Chemical Cleaning Service BPT Komdigi', 'Barang', 'E-Purchasing', 'Jawa Barat, Bekasi (Kab.)', 162500000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Uraian Umum Pekerjaan ini merupakan pengadaan kebutuhan operasional kebersihan gedung dan perawatan taman di lingkungan BPT Komdigi, yang meliputi penyediaan atribut personel, peralatan penunjang habis pakai, serta bahan kimia pembersih dan perawatan taman guna mendukung kegiatan kebersihan, sanitasi, pengendalian hama, serta pemeliharaan area dalam dan luar gedung. 2. Ruang Lingkup Pekerjaan Ruang lingkup pekerjaan meliputi pengadaan barang sebagai berikut: A. Atribut Personel Caddy bag Keset lobby Cangkul B. Penunjang Peralatan Habis Pakai Senar mesin potong rumput Steel wool Floor squeegee Frame lobby Kain lap kanebo Kain lap kotak Kain lap microfiber Kemoceng Rodentisida blok (anti tikus) Rat box station/trap Snake repel Snake tongs Mop complete Pengki kaleng Pengki plastik Plastik mop holder Plastik sampah Refill lobby duster Refill mop Refill washer Sapu lidi tanpa tangkai Kain pel lantai Sapu nylon Sarung tangan kain Sarung tangan karet Sikat kloset Sikat tangan plastik Kape besi Sikat tangkai kamar mandi Sikat tangkai halaman (kawat) Tangkai aluminium + hand grip Window squeegee Window washer Tissue roll besar Tissue kecil Tissue roll kecil Tissue wajah Sponge cuci piring Tong sampah besar Anti cicak Anti lalat C. Penunjang Jenis Bahan Kimia Floor cleaner Pembersih alat elektronik Urea Pestisida Pupuk kompos organik Cairan pembersih jalan setapak/bebatuan taman Zat perangsang tumbuhan Bait gel kecoa Desinfektan spray Fogging oil (base for thermal fogging) Alkohol 70% (desinfeksi alat pest control) Pengharum ruangan Pengharum ruangan gantung Pengharum ruangan gantung kamar mandi Reed diffuser Glass cleaner Multi cleaner Karbol Handsoap Bowl cleaner Kamper bola Detergen Kamper gantung', '1. Spesifikasi Umum Seluruh barang yang disediakan harus dalam kondisi baru, tidak cacat, dan layak pakai. Barang harus sesuai dengan standar kualitas kebersihan gedung perkantoran dan perawatan taman. Bahan kimia harus aman digunakan, tidak merusak permukaan, serta memenuhi standar keselamatan kerja. Produk bahan kimia harus memiliki izin edar yang berlaku (apabila dipersyaratkan sesuai ketentuan peraturan perundang-undangan). Pengemasan harus dalam kondisi baik, tersegel (untuk bahan kimia), dan mencantumkan label produk secara jelas. 2. Spesifikasi Teknis A. Atribut dan Peralatan Kebersihan Terbuat dari bahan yang kuat dan tahan lama. Ergonomis dan mudah digunakan oleh petugas kebersihan. Tidak mudah rusak dalam penggunaan rutin harian. B. Peralatan Pengendalian Hama Efektif dalam pengendalian tikus, serangga, dan hewan liar sesuai fungsinya. Aman digunakan di lingkungan perkantoran. Tidak membahayakan manusia apabila digunakan sesuai petunjuk. C. Bahan Kimia Pembersih Memiliki daya bersih optimal sesuai peruntukannya. Tidak meninggalkan residu berbahaya. Tidak menimbulkan bau menyengat yang mengganggu aktivitas kerja. Aman untuk berbagai jenis permukaan (lantai, kaca, keramik, logam, dan peralatan elektronik sesuai jenis produknya). D. Bahan Perawatan Taman Mendukung pertumbuhan dan kesehatan tanaman. Tidak merusak struktur tanah dan lingkungan sekitar. Digunakan sesuai dosis dan petunjuk teknis produk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2443037);
