INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65902496', 65902496, 'analyze_legacy', 'Provinsi Kalimantan Tengah', 'provinsi', 'Dinas Kependudukan dan Catatan Sipil', 'Pengadaan Pakaian Dinas Harian Beserta Atribut Kelengkapannya', 'Jasa Lainnya', 'Penunjukan Langsung', 'Kalimantan Tengah, Palangka Raya (Kota)', 80190000, 'September 2026', 'APBD', 1, 1, '99 stel', 'Jenis Pakaian: Terdiri dari PDH warna Khaki (untuk Senin-Selasa), PDH Kemeja Putih (untuk Rabu)sesuai peraturan Waktu Pelaksanaan: Pekerjaan biasanya harus diselesaikan dalam jangka waktu tertentu (misalnya 14 hingga 60 hari kalender) setelah diterbitkannya Surat Perintah Mulai Kerja (SPMK).', 'PDH Khaki: Menggunakan kain campuran katun dan polyester Kemeja Putih: Bahan katun atau synthetic blend yang menyerap keringat dan tidak mudah kusut. Standar Keamanan: Bahan tidak mengandung zat warna azo yang berbahaya dan kadar formaldehida di bawah 75 ppm. Karakteristik: Kain harus tidak luntur, tidak menyusut drastis setelah dicuci, dan memiliki sirkulasi udara yang baik. Model Pria: Kemeja lengan pendek dengan kerah berdiri, saku depan, dan celana panjang warna senada atau hitam. Model Wanita: Kemeja lengan pendek atau panjang (bagi yang berjilbab), rok atau celana panjang sesuai ketentuan instansi. Atribut Wajib: Papan Nama: Bahan akrilik atau kuningan dengan pengait magnet. Pin Korpri: Bahan kuningan dengan diameter minimal 3 cm. Logo Instansi: Bordir komputer dengan tingkat kerapihan tinggi di lengan kiri/kanan sesuai regulasi. 4. Standar Produksi dan Layanan Pengukuran: Penyedia wajib melakukan pengukuran manual atau menyediakan daftar ukuran standar (S, M, L, XL, XXL) sesuai kebutuhan pegawai. Kualitas Jahitan: Jahitan harus rapi (minimal 10-12 tusuk per inci), kuat, dan menggunakan benang yang warnanya sesuai dengan bahan kain. Pengemasan: Produk dikemas secara individual per unit/orang menggunakan plastik pelindung untuk menjaga kebersihan selama distribusi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2444090);
